const missions = [
  { id:'filter', level:'starter', category:'Débuter', short:'Filtrer les lignes', title:'Le comptoir des grandes ventes', xp:25, kicker:'Mission 01 · Filtrer', text:'Garde uniquement les ventes dont le montant dépasse 400. Utilise une expression booléenne sur le DataFrame.', code:"df[df['montant'] > 400]", expected:[/df\s*\[\s*df\s*\[\s*['\"]montant['\"]\s*\]\s*>\s*400\s*\]/,/df\.query\s*\(\s*['\"].*montant\s*>\s*400.*['\"]\s*\)/], hint:"La condition se place entre crochets : df[condition].", feedback:'Excellent. Tu sais isoler les observations qui répondent à un critère.', data:{headers:['ville','produit','montant'],rows:[['Kinshasa','Thé','420'],['Lubumbashi','Café','680'],['Goma','Thé','510'],['Bukavu','Jus','245']]}, datasetHint:'2 lignes seront écartées.' },
  { id:'columns', level:'starter', category:'Débuter', short:'Choisir les colonnes', title:'Le tableau de bord léger', xp:20, kicker:'Mission 02 · Sélectionner', text:'Le marketing veut seulement connaître la ville et le montant. Sélectionne ces deux colonnes dans cet ordre.', code:"df[['ville', 'montant']]", expected:[/df\s*\[\s*\[\s*['\"]ville['\"]\s*,\s*['\"]montant['\"]\s*\]\s*\]/], hint:"Pour plusieurs colonnes, utilise une liste de noms à l’intérieur de doubles crochets.", feedback:'Bien vu : réduire les variables rend une analyse plus lisible et plus rapide.', data:{headers:['ville','produit','montant'],rows:[['Kinshasa','Thé','420'],['Lubumbashi','Café','680'],['Goma','Thé','510'],['Bukavu','Jus','245']]}, datasetHint:'Tu dois obtenir 2 colonnes.' },
  { id:'missing', level:'core', category:'Fondamentaux', short:'Soigner les valeurs manquantes', title:'SOS, données incomplètes', xp:30, kicker:'Mission 03 · Nettoyer', text:'Les cellules vides du montant doivent devenir 0 pour préparer le calcul du chiffre d’affaires. Complète la colonne montant.', code:"df['montant'] = df['montant'].fillna(0)", expected:[/df\s*\[\s*['\"]montant['\"]\s*\]\s*=\s*df\s*\[\s*['\"]montant['\"]\s*\]\s*\.fillna\s*\(\s*0\s*\)/,/df\.fillna\s*\(\s*\{\s*['\"]montant['\"]\s*:\s*0\s*\}\s*\)/], hint:"fillna(0) remplace chaque valeur manquante par zéro. Tu peux cibler une seule colonne.", feedback:'Parfait. Tu viens d’éviter qu’une valeur absente ne perturbe une agrégation.', data:{headers:['ville','montant','vendeur'],rows:[['Kinshasa','420','Mia'],['Goma','—','Nora'],['Bukavu','245','Mia'],['Kisangani','—','Sam']]}, datasetHint:'Deux montants sont manquants.' },
  { id:'groupby', level:'core', category:'Fondamentaux', short:'Résumer par groupe', title:'Quel vendeur domine ?', xp:35, kicker:'Mission 04 · Agréger', text:'Calcule le total des ventes pour chaque vendeur. Groupe les lignes par vendeur, puis additionne la colonne montant.', code:"df.groupby('vendeur')['montant'].sum()", expected:[/df\.groupby\s*\(\s*['\"]vendeur['\"]\s*\)\s*\[\s*['\"]montant['\"]\s*\]\s*\.sum\s*\(\s*\)/,/df\.groupby\s*\(\s*['\"]vendeur['\"]\s*\)\s*\.agg\s*\(/], hint:"Commence par df.groupby('vendeur'), sélectionne la colonne montant, puis appelle sum().", feedback:'Oui ! groupby transforme une table de lignes en un résumé par catégorie.', data:{headers:['vendeur','montant','ville'],rows:[['Mia','420','Kinshasa'],['Nora','680','Goma'],['Mia','245','Bukavu'],['Nora','510','Goma']]}, datasetHint:'Il y aura une ligne par vendeur.' },
  { id:'merge', level:'core', category:'Fondamentaux', short:'Relier deux tables', title:'La jonction des mondes', xp:35, kicker:'Mission 05 · Joindre', text:'Ajoute le nom de la ville à chaque vente grâce à la clé ville_id. Conserve toutes les ventes, même si une ville manque.', code:"pd.merge(ventes, villes, how='left', on='ville_id')", expected:[/pd\.merge\s*\(\s*ventes\s*,\s*villes\s*,\s*how\s*=\s*['\"]left['\"]\s*,\s*on\s*=\s*['\"]ville_id['\"]\s*\)/,/ventes\.merge\s*\(\s*villes\s*,\s*how\s*=\s*['\"]left['\"]\s*,\s*on\s*=\s*['\"]ville_id['\"]\s*\)/], hint:"Une jointure gauche (left) préserve toutes les lignes de la table ventes.", feedback:'Réussi. Tu sais enrichir une table sans perdre ses lignes de départ.', data:{headers:['ville_id','montant','ville'],rows:[['1','420','Kinshasa'],['2','680','Goma'],['3','245','—'],['2','510','Goma']]}, datasetHint:'Pense à la table ventes comme table de gauche.' },
  { id:'dates', level:'advanced', category:'Explorer', short:'Extraire une date', title:'Le trimestre caché', xp:25, kicker:'Mission 06 · Dates', text:'La colonne date est déjà de type datetime. Crée une colonne trimestre qui indique le trimestre de chaque vente.', code:"df['trimestre'] = df['date'].dt.quarter", expected:[/df\s*\[\s*['\"]trimestre['\"]\s*\]\s*=\s*df\s*\[\s*['\"]date['\"]\s*\]\.dt\.quarter/], hint:"L’accesseur .dt expose des éléments de calendrier, dont quarter.", feedback:'Exact : les dates offrent beaucoup plus que leur texte brut.', data:{headers:['date','montant','trimestre'],rows:[['2026-01-18','420','?'],['2026-04-02','680','?'],['2026-09-11','245','?'],['2026-12-27','510','?']]}, datasetHint:'Le résultat va de 1 à 4.' },
  { id:'strings', level:'advanced', category:'Explorer', short:'Nettoyer les textes', title:'Les noms indisciplinés', xp:25, kicker:'Mission 07 · Texte', text:'Uniformise la casse de la colonne produit pour que chaque mot commence par une majuscule.', code:"df['produit'] = df['produit'].str.title()", expected:[/df\s*\[\s*['\"]produit['\"]\s*\]\s*=\s*df\s*\[\s*['\"]produit['\"]\s*\]\.str\.title\s*\(\s*\)/], hint:"Les opérations de texte vectorisées vivent derrière l’accesseur .str.", feedback:'Parfait. Tu as appliqué une règle à toute une série sans boucle Python.', data:{headers:['produit','ville','montant'],rows:[['café noir','Kinshasa','420'],['THÉ VERT','Goma','680'],['jus mangue','Bukavu','245'],['CAFE LATTE','Goma','510']]}, datasetHint:'Utilise une opération .str vectorisée.' },
  { id:'boss', level:'advanced', category:'Explorer', short:'Boss final : pipeline', title:'Le pipeline express', xp:50, kicker:'Mission 08 · Boss final', text:'Ne garde que les ventes supérieures à 400, puis trie-les de la plus grande à la plus petite. Enchaîne les deux opérations.', code:"df.query('montant > 400').sort_values('montant', ascending=False)", expected:[/query\s*\(\s*['\"].*montant\s*>\s*400.*['\"]\s*\)\s*\.sort_values\s*\(\s*['\"]montant['\"]\s*,\s*ascending\s*=\s*False\s*\)/,/df\s*\[\s*df\s*\[\s*['\"]montant['\"]\s*\]\s*>\s*400\s*\]\s*\.sort_values\s*\(\s*['\"]montant['\"]\s*,\s*ascending\s*=\s*False\s*\)/], hint:"Crée d’abord le sous-ensemble, puis enchaîne .sort_values(..., ascending=False).", feedback:'Boss vaincu. Tu as combiné deux transformations en une chaîne de méthodes lisible.', data:{headers:['ville','montant','produit'],rows:[['Kinshasa','420','Thé'],['Goma','680','Café'],['Bukavu','245','Jus'],['Goma','510','Thé']]}, datasetHint:'Ton résultat final doit être en ordre décroissant.' }
];

const skills=[
  ['▦','Manipuler','Créer, sélectionner et transformer un DataFrame.',[0,1]],['⌁','Nettoyer','Traiter les valeurs manquantes sans surprise.',[2]],['∑','Résumer','Grouper, compter et agréger avec confiance.',[3]],['⇄','Relier','Assembler des tables avec les bonnes jointures.',[4]],['◷','Temporaliser','Extraire les bonnes informations de tes dates.',[5]],['Aa','Normaliser','Appliquer des transformations de texte vectorisées.',[6]],['↗','Visualiser','Choisir une première représentation graphique.',[]],['⚑','Pipeline','Enchaîner des opérations lisibles et robustes.',[7]]
];
const references=[['Créer & sélectionner',"pd.DataFrame(...)",'Construire une table et viser les bonnes lignes ou colonnes.'],['Filtrer',"df.query('montant > 400')",'Exprimer clairement une condition sur tes observations.'],['Transformer',"df.assign(total=lambda d: ...)",'Créer une nouvelle colonne sans casser ton flux.'],['Résumer',"df.groupby('ville').sum()",'Faire parler les groupes avec sum, mean, count ou agg.'],['Joindre',"pd.merge(gauche, droite, how='left')",'Relier des jeux de données par une clé commune.'],['Examiner',"df.info() · df.describe()",'Comprendre formes, types et statistiques en quelques secondes.']];

const state = JSON.parse(localStorage.getItem('pandasQuestState') || '{"xp":0,"solved":[],"hints":[],"streak":0,"lastPlay":""}');
let current = Number(localStorage.getItem('pandasQuestCurrent') || 0);
let activeFilter = 'all';
const $ = id => document.getElementById(id);
const normalise = value => value.replace(/\s+/g,'').replace(/`/g,'').toLowerCase();

function renderMissionRail(){
  const visible = missions.filter(m=>activeFilter==='all'||m.level===activeFilter);
  $('missionRail').innerHTML = visible.map(m=>{const ix=missions.indexOf(m), done=state.solved.includes(m.id); return `<button class="mission-item ${ix===current?'active':''} ${done?'done':''}" data-index="${ix}"><span class="mission-number">${done?'✓':String(ix+1).padStart(2,'0')}</span><span><p>${m.category}</p><h4>${m.short}</h4></span><span class="lock">${done?'✦':m.xp+' XP'}</span></button>`}).join('');
  document.querySelectorAll('.mission-item').forEach(el=>el.addEventListener('click',()=>{current=Number(el.dataset.index);localStorage.setItem('pandasQuestCurrent',current);renderAll();}));
}
function renderDataset(m){$('datasetTable').innerHTML=`<div class="table-wrap"><table><thead><tr>${m.data.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${m.data.rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('datasetHint').textContent=m.datasetHint;}
function renderChallenge(){const m=missions[current];$('challengeCategory').textContent=m.category.toUpperCase();$('challengeStatus').textContent=`${String(current+1).padStart(2,'0')} / ${String(missions.length).padStart(2,'0')}`;$('challengeKicker').textContent=m.kicker;$('challengeTitle').textContent=m.title;$('challengeXP').textContent=m.xp;$('challengeText').textContent=m.text;$('codeInput').value=m.code;renderDataset(m);resetResult();}
function renderSkills(){ $('skillMap').innerHTML=skills.map(([icon,title,desc,ids])=>{const solved=ids.filter(i=>state.solved.includes(missions[i].id)).length;const pct=ids.length?solved/ids.length*100:state.solved.length>=5?100:0;return `<article class="skill-card"><span class="skill-icon">${icon}</span><h3>${title}</h3><p>${desc}</p><div class="skill-progress"><i style="width:${pct}%"></i></div></article>`}).join('');}
function renderReference(){ $('referenceGrid').innerHTML=references.map(([title,code,desc])=>`<article class="reference-card"><h3>${title}</h3><p>${code}</p><small>${desc}</small></article>`).join('');}
function updateStats(){const xp=state.xp;const level=Math.floor(xp/180)+1;const tier=xp%180;$('xpValue').textContent=`${xp} XP`;$('solvedValue').textContent=`${state.solved.length} / ${missions.length}`;$('streakValue').textContent=`${state.streak||0} jour${state.streak===1?'':'s'}`;$('levelLabel').textContent=`Niv. ${level}`;$('progressText').textContent=`${tier} / 180 XP`;$('progressFill').style.width=`${tier/1.8}%`;}
function renderAll(){renderMissionRail();renderChallenge();renderSkills();renderReference();updateStats();}
function persist(){localStorage.setItem('pandasQuestState',JSON.stringify(state));}
function result(kind,title,detail){const box=$('resultBox');box.className=`result-box ${kind}`;box.innerHTML=`<span class="result-icon">${kind==='success'?'✓':'!'}</span><div><b>${title}</b><p>${detail}</p></div>`;}
function resetResult(){result('','Prête à analyser.','Écris une solution puis vérifie-la : on te dira exactement ce qui fonctionne.');}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function celebrate(m){const first=!state.solved.includes(m.id); if(first){state.solved.push(m.id);state.xp+=m.xp;const day=new Date().toDateString();state.streak=state.lastPlay===day?state.streak:Math.max(1,(state.streak||0)+1);state.lastPlay=day;persist();updateStats();renderMissionRail();renderSkills();toast(`+${m.xp} XP · Mission validée !`);if(state.solved.length===missions.length) setTimeout(()=>toast('🏆 Carte complète : tu as vaincu tous les défis !'),500);} result('success','C’est juste !',m.feedback);}
function validate(){const m=missions[current], code=normalise($('codeInput').value);if(m.expected.some(rule=>rule.test(code))){celebrate(m)}else{result('error','Pas encore tout à fait.','Vérifie le nom de la colonne, la condition et les parenthèses. Un indice peut t’aider.');}}
function revealHint(){const m=missions[current];if(!state.hints.includes(m.id)){state.hints.push(m.id);state.xp=Math.max(0,state.xp-5);persist();updateStats();$('hintCost').textContent='déjà vu';}result('','Indice',m.hint);}
function nextMission(){current=(current+1)%missions.length;localStorage.setItem('pandasQuestCurrent',current);renderAll();document.querySelector('#missions').scrollIntoView({behavior:'smooth',block:'start'});}
document.querySelectorAll('.filter-tabs button').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;document.querySelectorAll('.filter-tabs button').forEach(x=>x.classList.toggle('active',x===b));renderMissionRail();}));
$('runBtn').addEventListener('click',validate);$('hintBtn').addEventListener('click',revealHint);$('skipBtn').addEventListener('click',nextMission);$('surpriseBtn').addEventListener('click',()=>{current=Math.floor(Math.random()*missions.length);localStorage.setItem('pandasQuestCurrent',current);renderAll();document.querySelector('#missions').scrollIntoView({behavior:'smooth',block:'start'});toast('Défi surprise sélectionné !');});$('dailyBtn').addEventListener('click',()=>{current=6;localStorage.setItem('pandasQuestCurrent',current);renderAll();document.querySelector('#missions').scrollIntoView({behavior:'smooth',block:'start'});toast('Défi quotidien chargé : à toi de jouer.');});$('resetProgress').addEventListener('click',()=>{if(confirm('Réinitialiser ta progression locale ?')){localStorage.removeItem('pandasQuestState');localStorage.removeItem('pandasQuestCurrent');location.reload();}});$('soundBtn').addEventListener('click',e=>{e.target.textContent=e.target.textContent.includes('off')?'♪ sons on':'♪ sons off';toast('Les petites victoires font toujours du bruit.');});$('codeInput').addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();validate();}});
$('dailyDate').textContent=new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short'}).format(new Date()).toUpperCase();renderAll();
